isolated_database(static function(PDO $db):void {
    $key=random_bytes(32);$codes=[];$otp=new OtpService($db,$key,static function($email,$subject,$body)use(&$codes):bool{preg_match('/[0-9]{6}/',$body,$m);$codes[$email]=$m[0];return true;});$auth=new AuthService($db,$otp);$night=new NightPrayerService($db,random_bytes(32));$api=new ApiKernel($db,$auth,new RateLimiter($db,$key),$night);
    $sessions=[];
