    $call=static fn(string $method,string $path,array $body=[],?string $authToken=null,array $query=[])=>$api->handle(new Request($method,'/api/v1'.$path,$body,['Authorization'=>'Bearer '.($authToken??$token)],$query));
    $id=test_uuid();$mutation=test_uuid();$data=['id'=>$id,'mutation_id'=>$mutation,'expected_revision'=>0,'night_date'=>'2026-03-28','timezone'=>'Europe/Berlin','boundary_source'=>'calculated','maghrib_at'=>'2026-03-28T18:00:00+01:00','fajr_at'=>'2026-03-29T06:00:00+02:00','entry_type'=>'range','start_index'=>1,'end_index'=>10,'measured_seconds'=>100,'note'=>'A private test note'];
    $created=$call('POST','/night-prayer/sessions',$data);assert_night($created->status===201,'range session created');assert_night($call('POST','/night-prayer/sessions',$data)->body['data']['revision']===1,'same mutation is idempotent');assert_night((int)$db->query('SELECT COUNT(*) FROM night_prayer_sessions')->fetchColumn()===1,'retry does not duplicate session');
    $read=$call('GET','/night-prayer/sessions/'.$id);assert_night($read->status===200&&$read->body['data']['note']===$data['note'],'owner reads decrypted note');assert_night($call('GET','/night-prayer/sessions/'.$id,[],$other)->status===404,'second user cannot read session');
    $cipher=$db->query('SELECT note_cipher FROM night_prayer_sessions')->fetchColumn();assert_night(!str_contains($cipher,$data['note']),'private note encrypted in database');assert_night(!str_contains($db->query('SELECT result_json FROM night_prayer_mutations')->fetchColumn(),$data['note']),'replay record contains no private note');
