    $manualId=test_uuid();$manual=['id'=>$manualId,'mutation_id'=>test_uuid(),'expected_revision'=>0,'night_date'=>'2026-03-28','timezone'=>'Europe/Berlin','entry_type'=>'manual','verse_count'=>90];assert_night($call('POST','/night-prayer/sessions',$manual)->status===201,'second same-night manual session');
    $stats=$call('GET','/night-prayer/analytics',[],null,['current_night'=>'2026-03-28']);assert_night($stats->body['data']['total_verses']===110&&$stats->body['data']['total_nights']===1,'nightly totals recomputed from live rows');assert_night($stats->body['data']['reading_pace']['seconds_per_verse']===5,'pace derives from measured sessions after edit');assert_night($stats->body['data']['continuation']['next']['global_index']===21,'continuation uses completed range');
    $noContext=$call('GET','/night-prayer/analytics');assert_night($noContext->body['data']['night_context_required']&&$noContext->body['data']['streaks'][1]['current']===null,'no midnight-based current-night invention');
    $cal=$call('GET','/night-prayer/calendar',[],null,['month'=>'2026-03']);assert_night(count($cal->body['data']['nights'])===1,'calendar maps fixed local night');
    $bad=$manual;$bad['id']=test_uuid();$bad['mutation_id']=test_uuid();$bad['exempt_dates']=['2026-03-27'];assert_night($call('POST','/night-prayer/sessions',$bad)->status===422,'exempt data rejected from server DTO');$bad=$data;$bad['id']=test_uuid();$bad['mutation_id']=test_uuid();$bad['verse_count']=999;assert_night($call('POST','/night-prayer/sessions',$bad)->status===422,'range count cannot be forged');
    $preferences=['expected_revision'=>0,'timezone'=>'Asia/Riyadh','city'=>'Riyadh'];assert_night($call('PUT','/night-prayer/preferences',$preferences)->status===200,'preferences saved');assert_night($call('PUT','/night-prayer/preferences',$preferences)->status===409,'preferences stale revision rejected');assert_night($call('GET','/night-prayer/sessions/'.$id)->body['data']['timezone']==='Europe/Berlin','travel preference does not move historical night');
    $remove=['mutation_id'=>test_uuid(),'expected_revision'=>2];assert_night($call('DELETE','/night-prayer/sessions/'.$id,$remove)->status===200,'session deleted');$tomb=$call('GET','/night-prayer/sessions/'.$id)->body['data'];assert_night(count($tomb)===3&&$tomb['deleted']===true,'tombstone contains no private context');assert_night($db->query('SELECT note_cipher FROM night_prayer_sessions WHERE id='.$db->quote($id))->fetchColumn()===null,'deletion clears ciphertext');assert_night($call('POST','/night-prayer/sessions',$data)->body['data']['revision']===1,'replaying old acknowledged mutation never resurrects data');assert_night($call('GET','/night-prayer/sessions/'.$id)->body['data']['deleted']===true,'old retry leaves deletion intact');
    $after=$call('GET','/night-prayer/analytics');assert_night($after->body['data']['total_verses']===90&&$after->body['data']['reading_pace']===null&&$after->body['data']['continuation']===null,'deletion recomputes pace and continuation');
    $sync=$call('POST','/night-prayer/sync',['cursor'=>0,'operations'=>[]]);$changes=$sync->body['data']['changes'];assert_night(count($changes)===2&&$sync->body['data']['next_cursor']>0,'sync deduplicates latest state and advances cursor');$hasTomb=false;foreach($changes as $change)if($change['id']===$id)$hasTomb=$change['deleted'];assert_night($hasTomb,'sync publishes minimal tombstone');
    $db->prepare("UPDATE users SET role='admin' WHERE id=?")->execute([$sessions[1]['user']['id']]);assert_night($call('GET','/night-prayer/sessions/'.$manualId,[],$other)->status===404,'administrator has no private-session bypass');
    $timerId=test_uuid();$timer=['id'=>$timerId,'mutation_id'=>test_uuid(),'expected_revision'=>0,'night_date'=>'2026-03-28','timezone'=>'UTC','boundary_source'=>'calculated','calculation_method'=>'EGYPTIAN','maghrib_at'=>'2026-03-28T18:00:00Z','fajr_at'=>'2026-03-29T05:00:00Z','started_at'=>'2026-03-28T23:59:58Z','ended_at'=>'2026-03-29T00:00:03Z','measured_seconds'=>5,'entry_type'=>'manual','verse_count'=>10,'note'=>'Fixture measured timer'];
    $measured=$call('POST','/night-prayer/sessions',$timer);assert_night($measured->status===201&&$measured->body['data']['revision']===1,'measured foreground timer DTO accepted');
    $measuredRead=$call('GET','/night-prayer/sessions/'.$timerId);assert_night($measuredRead->body['data']['measured_seconds']===5&&$measuredRead->body['data']['night_date']==='2026-03-28'&&$measuredRead->body['data']['ended_at']==='2026-03-29T00:00:03Z','measured cross-midnight session keeps Maghrib date and verified endpoint');
    assert_night($call('POST','/night-prayer/sessions',$timer)->body['data']['revision']===1,'measured timer outbox replay stays idempotent');
    $tooLong=$timer;$tooLong['id']=test_uuid();$tooLong['mutation_id']=test_uuid();$tooLong['measured_seconds']=11;assert_night($call('POST','/night-prayer/sessions',$tooLong)->status===422,'measured seconds cannot exceed verified elapsed interval plus API rounding tolerance');
    $beforeNight=$timer;$beforeNight['id']=test_uuid();$beforeNight['mutation_id']=test_uuid();$beforeNight['started_at']='2026-03-28T17:59:00Z';assert_night($call('POST','/night-prayer/sessions',$beforeNight)->status===422,'measured start cannot precede selected Maghrib');
    $afterFajr=$timer;$afterFajr['id']=test_uuid();$afterFajr['mutation_id']=test_uuid();$afterFajr['ended_at']='2026-03-29T05:00:01Z';assert_night($call('POST','/night-prayer/sessions',$afterFajr)->status===422,'measured endpoint cannot cross selected Fajr');
    assert_night($call('DELETE','/night-prayer/sessions/'.$timerId,['mutation_id'=>test_uuid(),'expected_revision'=>1])->status===200,'measured fixture cleanup uses ordinary owned deletion');
    $db->exec("INSERT INTO platform_settings (setting_key,setting_value) VALUES ('night_prayer_enabled','0')");$disabled=$manual;$disabled['id']=test_uuid();$disabled['mutation_id']=test_uuid();assert_night($call('POST','/night-prayer/sessions',$disabled)->status===503,'module disable blocks new writes');assert_night($call('DELETE','/night-prayer/sessions/'.$manualId,['mutation_id'=>test_uuid(),'expected_revision'=>1])->status===200,'disable does not prevent private deletion');
